package android.content;import android.content.pm.*;import android.content.res.*;import android.os.*;import java.util.*;public class Context {public static final String POWER_SERVICE="power",ACTIVITY_SERVICE="activity",ALARM_SERVICE="alarm",NOTIFICATION_SERVICE="notification";public String pkg="cn.hydrogen.launcher";public String getPackageName(){return pkg;}public Context getApplicationContext(){return this;}public Object getSystemService(String k){return fixture.Env.services.get(k);}public PackageManager getPackageManager(){return new PackageManager();}public Resources getResources(){return new Resources();}public AssetManager getAssets(){return new AssetManager(pkg);}public SharedPreferences getSharedPreferences(String n,int mode){return fixture.Env.prefs.computeIfAbsent(n,k->new SharedPreferences());}public Context createPackageContext(String p,int f){Context c=new Context();c.pkg=p;return c;}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f){fixture.Env.receivers.add(r);return null;}public Intent registerReceiver(BroadcastReceiver r,IntentFilter f,String p,Handler h){fixture.Env.receivers.add(r);return null;}public void unregisterReceiver(BroadcastReceiver r){fixture.Env.receivers.remove(r);}public void startActivity(Intent i){if(fixture.Env.blockHome&&"cn.hydrogen.launcher".equals(i.getComponent().getPackageName()))throw new SecurityException("injected HOME launch failure");fixture.Env.launches.add(i);fixture.Env.top=i.getComponent().getPackageName();}public void sendBroadcast(Intent i){fixture.Env.broadcasts.add(i);if(fixture.Env.route!=null)fixture.Env.route.accept(this,i);}public ComponentName startService(Intent i){fixture.Env.serviceStarts.add(i);if(i.getComponent().getClassName().equals("cn.hydrogen.launcher.StartupSequenceService"))fixture.Env.dispatch(i);return i.getComponent();}public ComponentName startForegroundService(Intent i){return startService(i);} }